import { installPlayback } from './playback/transport.js';
import { installSegmentView } from './segment-view.js';
import { installChrome } from './chrome.js';
import { installTools } from './tools.js';
import { installAppearance } from './appearance.js';
import { view } from './dom.js';
import { state } from './state.js';
import { ROW } from './constants.js';
import { draw } from './painting.js';
import { layout } from './viewport.js';
import { refresh } from './commands.js';
import { setTool } from './toolbar.js';
import { installPointer } from './pointer.js';
import { installToolbar } from './toolbar.js';
import { installInspector } from './inspector.js';
import { installInstruments } from './instruments.js';
import { installHistory } from './history.js';
import { installKeyboard } from './keyboard.js';
import { installFiles } from './files.js';
import { installExport } from './export.js';
// Composition root: wire modules once, then initialize the editor.
installPointer();
installChrome();
installTools();
installToolbar();
installSegmentView();
installInspector();
installInstruments();
installHistory();
installKeyboard();
installFiles();
installExport();
view.onscroll = draw;
new ResizeObserver(layout).observe(view);
setTool('draw');
refresh();
installAppearance();
view.scrollTop = (state.topPitch - 78) * ROW;
draw();
installPlayback();
